document.write("<!-- 🔤 Lettercraft extra words (lc-2, 2026-11-08): 63832 more real words for CHECKING a play only (the robot keeps its own everyday list).\n Source: SCOWL word lists up to size 70 (American + British + Canadian + Australian spellings, incl. word forms: plurals, -ed, -ing, -er, -est …) + newer dictionary words (EMOJI, SELFIE, WEBSITE, PODCAST …),\n kid-filtered (rude words, weapons / drink / drugs / smoking / killing words left out). Rebuild offline — do not edit by hand. Stored front-coded since sz-1 (Test Harness/patch_sz1.py packs a plain list). -->\n<script>\n// 📦 sz-1: front-coded (digit = letters shared with the word before, then the rest) — unpacked here into the same space-separated string\nwindow.WORDS_EXTRA = (function(c){ const out = []; let prev = '', i = 0; while(i < c.length){ const k = c.charCodeAt(i) - 48; i++; let j = i; while(j < c.length){ const d = c.charCodeAt(j); if(d >= 48 && d <= 57) break; j++; } const w = prev.slice(0, k) + c.slice(i, j); out.push(w); prev = w; i = j; } return out.join(' '); })('');\n</script>\n<!-- (lc-2+sz-1) END OF WordExtra.html -->\n");
